import collections
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==4 or (r,c) in seen: continue
  q=[(r,c)]; seen.add((r,c)); pts=[]
  while q:
   p=q.pop(); pts.append(p)
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     nr,nc=p[0]+dr,p[1]+dc
     if (dr or dc) and 0<=nr<R and 0<=nc<C and grid[nr][nc]==col and (nr,nc) not in seen:
      seen.add((nr,nc));q.append((nr,nc))
  comps.append((col,len(pts),(min(a for a,b in pts),max(a for a,b in pts),min(b for a,b in pts),max(b for a,b in pts)),pts))
[(co,n,box) for co,n,box,pts in comps]

